#!/usr/bin/env python3
"""Apply the reviewed VCS Card Details refresh, with conflict checks and undo.

Run from VirtualCardShop or virtual-card-shop. Requires Python 3, Git, Node, npm.
Default: check all files, back up, apply, run unit tests and production build.
--check: inspect compatibility without writing. --apply-only: skip npm validation.
No database migration, Git commit, push, or deployment is performed.
"""
import argparse
import base64
import datetime
import gzip
import hashlib
import json
import os
from pathlib import Path
import shlex
import shutil
import subprocess
import sys
import tempfile
import uuid

BASE_COMMIT = "385306bcc65562a6e0ed7a7434730badd5786076"
PAYLOAD = ""


def digest(data):
    return hashlib.sha256(data).hexdigest()


def safe_path(root, relative):
    rel = Path(relative)
    if rel.is_absolute() or ".." in rel.parts:
        raise RuntimeError("Unsafe package path: " + relative)
    target = root
    for part in rel.parts:
        target = target / part
        if target.is_symlink():
            raise RuntimeError("Refusing to replace a symbolic link: " + str(target))
    if target.exists() and not target.is_file():
        raise RuntimeError("Expected a file: " + str(target))
    return target


def atomic_write(path, data, mode=0o644):
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, temporary = tempfile.mkstemp(prefix=".vcs-card-details-", dir=path.parent)
    try:
        with os.fdopen(fd, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.chmod(temporary, mode)
        os.replace(temporary, path)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)


def restore(directory):
    manifest = json.loads((directory / "manifest.json").read_text())
    root = Path(manifest["app"])
    work = []
    for item in manifest["files"]:
        path = safe_path(root, item["path"])
        current = path.read_bytes() if path.exists() else None
        current_hash = digest(current) if current is not None else None
        if current_hash == item["before"]:
            continue
        if current_hash != item["after"]:
            raise RuntimeError("Undo stopped: later edits found in " + str(path))
        original = (directory / "originals" / item["path"]).read_bytes() if item["before"] else None
        if original is not None and digest(original) != item["before"]:
            raise RuntimeError("Backup integrity check failed: " + item["path"])
        work.append((path, original, item["mode"]))
    for path, original, mode in work:
        if original is None:
            path.unlink()
        else:
            atomic_write(path, original, mode)
    print("Restored", len(work), "files. Restart your dev server, or rebuild before serving production.")


def locate_app():
    result = subprocess.run(["git", "rev-parse", "--show-toplevel"], text=True, capture_output=True)
    if result.returncode:
        raise RuntimeError("Open a terminal inside your VirtualCardShop Git checkout, then run this command again.")
    root = Path(result.stdout.strip()).resolve()
    for candidate in (root / "virtual-card-shop", root):
        package = candidate / "package.json"
        if package.is_file() and json.loads(package.read_text()).get("name") == "virtual-card-shop":
            return candidate
    raise RuntimeError("Could not locate virtual-card-shop/package.json in this Git checkout.")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    parser.add_argument("--apply-only", action="store_true")
    parser.add_argument("--restore", type=Path, help=argparse.SUPPRESS)
    args = parser.parse_args()
    if args.restore:
        restore(args.restore.resolve())
        return
    if not shutil.which("git"):
        raise RuntimeError("Git is required.")
    app = locate_app()
    package = json.loads(gzip.decompress(base64.b64decode(PAYLOAD)))
    changes, conflicts = [], []
    for entry in package:
        path = safe_path(app, entry["path"])
        current = path.read_bytes() if path.exists() else None
        current_hash = digest(current) if current is not None else None
        new = entry["content"].encode("utf-8")
        if digest(new) != entry["after"]:
            raise RuntimeError("Package integrity check failed: " + entry["path"])
        if current_hash == entry["after"]:
            continue
        if current_hash != entry["before"]:
            conflicts.append(entry["path"])
            continue
        changes.append((entry, path, current, new))
    if conflicts:
        raise RuntimeError("No files changed. These files differ from the reviewed version (" + BASE_COMMIT[:12] + "):\n  " + "\n  ".join(conflicts) + "\nKeep your edits and have the update reconciled with these files; this installer will not overwrite them.")
    print("App:", app, flush=True)
    print(f"Compatibility passed: {len(changes)} files to update; {len(package) - len(changes)} already current.", flush=True)
    if args.check or not changes:
        return
    if not args.apply_only:
        for executable in ("node", "npm"):
            if not shutil.which(executable):
                raise RuntimeError(executable + " is required. No files changed.")
    git_backup = subprocess.check_output(["git", "rev-parse", "--git-path", "vcs-card-details-backups"], cwd=app, text=True).strip()
    backup_root = Path(git_backup)
    if not backup_root.is_absolute():
        backup_root = app / backup_root
    stamp = datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%dT%H%M%SZ") + "-" + uuid.uuid4().hex[:8]
    backup = (backup_root / stamp).resolve()
    backup.mkdir(parents=True)
    manifest = {"app": str(app), "baseCommit": BASE_COMMIT, "files": []}
    for entry, path, original, new in changes:
        mode = (path.stat().st_mode & 0o777) if original is not None else 0o644
        if original is not None:
            atomic_write(backup / "originals" / entry["path"], original, mode)
        manifest["files"].append({"path": entry["path"], "before": entry["before"], "after": entry["after"], "mode": mode})
    atomic_write(backup / "manifest.json", json.dumps(manifest, indent=2).encode())
    atomic_write(backup / "restore.py", Path(__file__).read_bytes())
    undo = "python3 " + shlex.quote(str(backup / "restore.py")) + " --restore " + shlex.quote(str(backup))
    atomic_write(backup / "UNDO.txt", (undo + "\n").encode())
    # Recheck every touched file immediately before the write phase.
    for entry, path, original, new in changes:
        if (path.read_bytes() if path.exists() else None) != original:
            raise RuntimeError("A file changed during preflight. No update applied: " + str(path))
    completed = []
    try:
        for (entry, path, original, new), record in zip(changes, manifest["files"]):
            atomic_write(path, new, record["mode"])
            completed.append((path, original, record["mode"]))
    except BaseException:
        for path, original, mode in reversed(completed):
            if original is None:
                path.unlink(missing_ok=True)
            else:
                atomic_write(path, original, mode)
        raise
    print("\nUpdated", len(changes), "files. Backup:", backup, flush=True)
    print("Undo command:\n" + undo + "\n", flush=True)
    if not args.apply_only:
        environment = dict(os.environ)
        environment.setdefault("NEXT_TURBOPACK_EXPERIMENTAL_USE_SYSTEM_TLS_CERTS", "1")
        try:
            if not all((app / "node_modules" / ".bin" / name).exists() for name in ("tsx", "prisma", "next")):
                subprocess.run(["npm", "ci"], cwd=app, env=environment, check=True)
            subprocess.run(["node", "--import", "tsx", "--test", "tests/card-details.test.ts"], cwd=app, env=environment, check=True)
            subprocess.run(["npm", "run", "build"], cwd=app, env=environment, check=True)
        except (subprocess.CalledProcessError, KeyboardInterrupt) as error:
            raise RuntimeError("Validation did not finish successfully. Updated files and backups are retained. Resolve the reported build/test error or undo with:\n" + undo) from error
        print("\nCard Details refresh applied. Tests and production build passed.", flush=True)
    else:
        print("Applied; validation skipped (--apply-only).", flush=True)
    print("Restart your dev server to preview. No Git commit, push, database migration, or deployment was performed.")


if __name__ == "__main__":
    try:
        main()
    except Exception as error:
        print("\nSTOPPED:", error, file=sys.stderr)
        sys.exit(1)
